  <script>
import MarkerIconPicker from '@/components/MarkerIconPicker'
import defaultHotpotConfig from '@/config/vr-hotpot'
import {
  getProduct,
  makeHotpot,
  clearHotpots,
  removeHotpot,
  showHotpot,
  getHotpointTypeItems,
} from '@/api/vr'
// eslint-disable-next-line no-unused-vars
import { debounce, cloneDeep, merge, omit } from 'lodash'
import { validateURL, validateVideoURL } from '@/utils/tools'
// eslint-disable-next-line no-unused-vars
// import DrawTool from '@/utils/DrawTool'
const defaultModel = {
  id: undefined,
  uuid: undefined,
  productId: undefined, // 当前作品ID
  sceneId: undefined, // 当前场景ID
  userId: undefined, // 当前添加人ID
  icon: 'front_gif', // 图标内容
  iconType: 'vr', // vr=专用图标;element=内置图标;polygon=区域图标;polyline=线条图标;custom=自定义图标（这种方式是用户自己上传，前端用imageLayer展示)
  iconSize: 'mini', // big:大; medium:中等 ;mini：小型
  type: 'text', // sceneChange=全景切换;hyperlink=超链接;image=图片热点;video=视频热点;text=文本热点;
  longitude: '', // 经度
  latitude: '', // 维度
  title: '', // 标题
  titleFontSize: 12, // 12 14 16 标题大小
  titleFontColor: '#fff',
  imgUrls: [], // 多张图片前端以相册方式展示
  toSceneId: null, // 全景切换目标场景ID
  link: '', // 超链接地址
  linkTarget: '_blank',
  // 超链接打开方式
  videoUrl: '', // 视频地址（支持mp4 m3u8 flv)
  content: '', // 文本内容
  iotDeviceType: '', // weather=气象；soil=墒情;pest=虫情;ctrl=智能控制设备
  iotShowMode: 'table', // echart=图表展示;table=表格展示;
  iotApiUrl: '', //数据源接口地址
  iconMarkerParams: null, // 当前图标对应的marker参数
  iconTitleMarkerParams: null, // 当前图标标题对应的marker参数
}
export default {
  name: 'HotpotSidebar',
  props: {
    productId: undefined,
  },
  data() {
    return {
      hotpots: [],
      btnDisabled: false,
      hotDrawer: false,
      iconTab: 'vr',
      sceneId: null,
      hotModel: Object.assign({}, defaultModel),
      typeOptions: [],
      allScenes: [],
      scenes: [],
      currentMarkerOptions: null,
      saveHotpoted: false,
      updateHot: false,
      markerPlugin: null,
      drawToolForm: {
        type: 'line',
        switch: 'off',
        lineColor: '#fff',
        bgColor: '#fff',
        points: [],
        rectangle: 'off',
      },
      drawTool: null,
      savePolygonLoading: false,
      iotDevice: null,
    }
  },
  components: {
    MarkerIconPicker,
    VrUpload: () => import('@/components/VrUpload.vue'),
    IotDialog: () => import('./IotDialog.vue'),
  },
  computed: {
    title() {
      return this.hotModel && this.hotModel.id ? '更新热点' : '添加热点'
    },
    otherScenes() {
      return this.allScenes.filter((scene) => {
        return scene.id !== this.sceneId
      })
    },
    imgFileList() {
      return this.hotModel.imgUrls.map((item, index) => {
        return { id: `img${index + 1}`, url: item }
      })
    },
  },
  watch: {
    iconTab(newVal, oldVal) {
      if (newVal !== oldVal) {
        this.$set(this.hotModel, 'iconType', newVal)
        this.drawToolForm = {
          type: 'line',
          switch: 'off',
          lineColor: '#fff',
          bgColor: '#fff',
          points: [],
        }
      }
    },
  },
  created() {
    this.getHotpointTypeItems()
    // VR 加载
    // eslint-disable-next-line no-unused-vars
    this.$bus.$on('onVrReady', (_viewer, _scene) => {
      this.btnDisabled = false
      this.sceneId = _scene.id
    })

    // eslint-disable-next-line no-unused-vars
    this.$bus.$on('onSceneChange', (scene) => {
      this.btnDisabled = true
    })
    // 点击修改标记
    // eslint-disable-next-line no-unused-vars
    this.$bus.$on('onClickUpdateMarker', (marker) => {
      showHotpot(marker.id).then((hotpot) => {
        if (!hotpot) {
          return false
        }
        this.updateHot = true
        this.hotDrawer = true
        this.hotModel = hotpot
        this.iconTab = this.hotModel.iconType ?? 'vr'
        console.log(
          'onHotDrawer update hotModel:',
          this.hotModel,
          this.iconTab
        )
        if (
          this.hotModel.type === 'iot' &&
          this.hotModel.iconMarkerParams.data.iotDevice
        ) {
          this.iotDevice = this.hotModel.iconMarkerParams.data.iotDevice
        }
        this.$nextTick(() => {
          this.$bus.$emit('onHotDrawerStatusChange', this.hotDrawer)
          if (this.iconTab !== 'polygon') {
            if (this.$refs.iconPicker) {
              this.$refs.iconPicker.changeKey(this.hotModel.icon)
            }

            if (this.$refs.elementIconPicker) {
              this.$refs.elementIconPicker.changeKey(this.hotModel.icon)
            }
          }
        })

        if (this.iconTab === 'polygon') {
          this.$nextTick(() => {
            this.drawToolForm.bgColor = this.hotModel.iconMarkerParams.svgStyle.fill
            this.drawToolForm.lineColor = this.hotModel.iconMarkerParams.svgStyle.stroke
          })
        }
      })
      // const position = marker.props.position
      // this.vrMarkerHot(markersPlugin, position)
    })
  },
  methods: {
    async getHotpointTypeItems() {
      this.typeOptions = await getHotpointTypeItems()
    },
    // eslint-disable-next-line no-unused-vars
    init(markerPlugin, hotpots, _viewer, currentSceneId) {
      this.markerPlugin = markerPlugin
      this.hotpots = hotpots
      if (currentSceneId) this.sceneId = currentSceneId
      // this.drawTool = new DrawTool(_viewer.renderer.renderer.domElement, {
      //   vrContainer: _viewer.container
      // })
    },
    updateHotpotPosition(index, position) {
      // console.log('i:', index, 'p:', position)
      this.hotpots[index].iconMarkerParams.position = position
      if (this.hotpots[index].id === this.hotModel.id) {
        this.hotModel.iconMarkerParams.position = position
      }
    },
    onHotDrawer(sceneId, position) {
      if (['polyline', 'custom'].includes(this.hotModel.iconType)) {
        this.$message.error('暂不支持该类型图标标记热点')
        return false
      }

      if (this.hotModel.iconType === 'polygon') {
        return true
      }

      if (!this.hotModel.type) {
        this.$message.error('请先选择热点类型在继续标注')
        return false
      }

      this.sceneId = sceneId
      this.vrMarkerHot(this.markerPlugin, position)
    },
    // eslint-disable-next-line no-unused-vars
    onTypeChange(val) {
      this.hotModel.title = ''
    },
    // 获取作品信息
    getProduct() {
      getProduct(this.productId).then((product) => {
        // this.$set(this.hotModel, 'sceneId', product.currentScene.id)
        this.allScenes = product.scenes
      })
    },
    // 生成 标记参数
    generateMarkerOptions(position, index = 1, otherOptions = {}) {
      let uuid = this.hotModel.uuid
      if (!uuid) {
        uuid = `${this.productId}_${
          this.sceneId
        }_${new Date().getTime()}_${index}`
        this.hotModel.uuid = uuid
      }
      const options = Object.assign(
        {
          id: uuid,
          title: this.hotModel.title,
          anchor: defaultHotpotConfig.anchor,
          orientation: defaultHotpotConfig.orientation,
          position: position,
          data: {
            titleFontSize: this.hotModel.titleFontSize,
            titleFontColor: this.hotModel.titleFontColor,
            iconType: this.hotModel.iconType,
            productId: this.productId,
            sceneId: this.sceneId,
            hotType: this.hotModel.type,
          },
        },
        otherOptions
      )

      if (options.title) {
        options.tooltip = {
          content: options.title,
          position: defaultHotpotConfig.tooltipPosition,
        }
      }
      
      if (this.hotModel.iconType === 'vr') {
        const { width, height } = this.getIconSize(this.hotModel.iconSize)
        if (this.hotModel.icon.indexOf('_gif') >= 0) {
          // 表明使用gif
          const sizeClass =
            this.hotModel.iconSize === 'mini' ? '' : this.hotModel.iconSize
          const prevClass =
            this.hotModel.icon === 'dot_gif' ? '' : 'marker-animate-gif'
          const v2Class =
            this.hotModel.icon.indexOf('v2_') >= 0
              ? 'marker-animate-v2-gif'
              : ''
          options.html = `<div class='${prevClass} ${v2Class} marker-animate-${this.hotModel.icon} ${sizeClass}'></div>`
        } else if (this.hotModel.icon.indexOf('_3d') >= 0) {
          options.imageLayer = require(`@/assets/default/icons/${this.hotModel.icon}.png`)
          options.width = width
          options.height = height
        } else {
          options.image = require(`@/assets/default/icons/${this.hotModel.icon}.png`)
          options.width = width
          options.height = height
        }
      } else if (this.hotModel.iconType === 'element') {
        options.html = `<i class='${this.hotModel.icon}'></i>`
      }
      let titleOptions = null
      if (this.hotModel.iconType !== 'polygon') {
        switch (this.hotModel.type) {
          // 根据不同的热点类型生成不同的marker标记对象参数
          case 'sceneChange':
            if (!this.hotModel.toSceneId) {
              this.$message.error('目标场景必须选择')
              return false
            }
            options.data.toSceneId = this.hotModel.toSceneId
            break
          case 'hyperlink':
            if (!validateURL(this.hotModel.link)) {
              this.$message.error('超链接地址格式错误')
              return false
            }
            options.data.link = this.hotModel.link
            options.data.linkTarget = this.hotModel.linkTarget
            break
          case 'image':
            if (!this.hotModel.imgUrls.length) {
              this.$message.error('请至少上传一张图片')
              return false
            }
            options.data.imgUrls = this.hotModel.imgUrls
            break
          case 'video':
            if (!validateVideoURL(this.hotModel.videoUrl)) {
              this.$message.error('视频地址格式错误')
              return false
            }
            options.data.videoUrl = this.hotModel.videoUrl
            break
          case 'text':
            if (!options.title) {
              this.$message.error('请输入文本标题')
              return false
            }
            // 文本热点不需要展示图标
            // eslint-disable-next-line no-case-declarations
            //
            options.image = null
            options.imageLayer = null
            // eslint-disable-next-line no-case-declarations
            let iconHtml = ''
            if (options.html) {
              iconHtml = options.html
            } else if (options.image) {
              iconHtml = `<div class="marker-icon"><img src="${options.image}" /></div>`
            } else if (options.imageLayer) {
              iconHtml =  `<div class="marker-icon"><img src="${options.imageLayer}" /></div>`
            }
            options.html = `<div class="marker-text">
              <div class="marker-title" style="font-size:${options.data.titleFontSize}px;font-weight:bold;color:${options.data.titleFontColor}">${options.title}</div>
              ${iconHtml}
              </div>`
            // options.title = ''
            options.tooltip = null
            options.content = this.hotModel.content
            break
          case 'iot':
            options.data.iotDevice = this.iotDevice
            break
          default:
            break
        }

        if (this.hotModel.type !== 'text' && options.title) {
          const beforeHtml = options.html
          if (!beforeHtml) {
            options.html = ''
            if (options.image) {
              options.html = `<img src="${options.image}" alt="${options.title}"/>`
            }

            if (options.imageLayer) {
              options.html = `<img src="${options.imageLayer}" alt="${options.title}"/>`
            }
          }
          options.image = null
          options.imageLayer = null
          options.html = `<div class="hotpoint-marker flex-center"><div class="hotpoint-marker-content ${this.hotModel.icon} ${this.hotModel.iconSize}">${options.html}</div><div class="marker-title" style="font-size:${options.data.titleFontSize}px;font-weight:bold;color:${options.data.titleFontColor};">${options.title}</div></div>`
        }
      } else {
        options.polygon = position
        options.title = this.hotModel.title
        options.svgStyle = {
          fill: this.drawToolForm.bgColor, // White color 'rgba(255, 255, 255, 1)'
          stroke: this.drawToolForm.lineColor,
        }
      }
      // console.log('options:', options)
      return { options, titleOptions }
    },
    // 生成标记的热点
    // eslint-disable-next-line no-unused-vars
    vrMarkerHot(markerPlugin, position) {
      const { options, titleOptions } = this.generateMarkerOptions(
        position,
        markerPlugin ? markerPlugin.getMarkers().length + 1 : 0
      )

      if (!options) {
        return false
      }

      this.currentMarkerOptions = options
      // console.log('vrMarkerHot.options:', options)
      markerPlugin.addMarker(options)
      this.hotModel.iconMarkerParams = options
      if (titleOptions) {
        markerPlugin.addMarker(titleOptions)
        this.hotModel.iconTitleMarkerParams = titleOptions
      }
      // api
      if (this.saveHotpoted) {
        return false
      }
      this.saveHotpoted = true

      this.hotModel.productId = this.productId
      this.hotModel.sceneId = this.sceneId
      makeHotpot(this.hotModel)
        .then((hotpot) => {
          this.saveHotpoted = false
          this.reset()
          this.hotDrawer = false
          // 保留不是当前修改的热点 （true：保留；false：过滤
          this.hotpots = this.hotpots.filter((item) => item.id !== hotpot.id)
          // this.hotpots = this.hotpots.filter(item => item.uuid !== hotpot.uuid)
          this.hotpots.unshift(hotpot)
        })
        .catch((_err) => {
          this.$message.error(_err.message)
          this.hotDrawer = false
        })
    },
    async addPolygonMarker(marker, index = 1) {
      // 如果要设置标题,需要使用svg参数或者自定义element
      marker.id = `${this.productId}_${this.sceneId}_${marker.id}`
      this.hotModel.uuid = marker.id
      const { options } = this.generateMarkerOptions(
        marker.position,
        index,
        marker
      )
      options.polygon = marker.polygon
      options.svgStyle = marker.svgStyle

      this.currentMarkerOptions = options
      this.hotModel.iconMarkerParams = options
      // api
      if (this.saveHotpoted) {
        return false
      }
      this.saveHotpoted = true

      this.hotModel.productId = this.productId
      this.hotModel.sceneId = this.sceneId
      await makeHotpot(this.hotModel)
        .then((hotpot) => {
          this.saveHotpoted = false
          this.reset()
          this.hotDrawer = false
          // 保留不是当前修改的热点 （true：保留；false：过滤
          this.hotpots = this.hotpots.filter((item) => item.id !== hotpot.id)
          this.hotpots.unshift(hotpot)
        })
        .catch((_err) => {
          this.$message.error(_err.message)
          this.hotDrawer = false
        })
      return marker.id
    },
    gotoMarker(markerId) {
      try {
        this.markerPlugin.gotoMarker(markerId)
        // eslint-disable-next-line no-empty
      } catch (_err) {
        console.log('gotoMarker error:', _err.message)
      }
    },
    // 修改热点
    onUpdHotpot() {
      // console.log('this.hotModel.iconMarkerParams:', this.hotModel.iconMarkerParams)
      const { options, titleOptions } = this.generateMarkerOptions(
        'polygon' === this.hotModel.iconType ? this.hotModel.iconMarkerParams.polygon : this.hotModel.iconMarkerParams.position
      )
      // console.log('upd after hotpot: ', this.hotModel)
      // return true
      
      // eslint-disable-next-line no-unreachable
      this.hotModel.iconMarkerParams = options
      this.hotModel.iconTitleMarkerParams = titleOptions
      // eslint-disable-next-line no-unused-vars
      makeHotpot(this.hotModel).then((_result) => {
        const hotpotIndex = this.hotpots.findIndex(
          (item) => item.uuid == this.hotModel.uuid
        )
        if (hotpotIndex >= 0) {
          this.hotpots[hotpotIndex].title = this.hotModel.title
          this.hotpots[hotpotIndex].iconMarkerParams =
            this.hotModel.iconMarkerParams
          this.hotpots[hotpotIndex].iconTitleMarkerParams =
            this.hotModel.iconTitleMarkerParams
        }
        this.$bus.$emit('onUpdHotpot', this.hotModel)
        this.updateHot = false
        this.hotDrawer = false
        this.reset()
      })
    },
    // 保存区域
    savePolygonMarkers() {
      this.savePolygonLoading = true
    },
    // 修改标记和重置位置标记
    onUpdAndResetPositionHotpot() {
      // 清空标记
      this.$bus.$emit('onRemoveHotpot', this.hotModel)
    },
    onDelHotpoint(hotModel) {
      this.$confirm('确认要删除改热点吗？', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
      })
        .then(() => {
          // eslint-disable-next-line no-unused-vars
          removeHotpot(hotModel.id).then((result) => {
            this.hotpots = this.hotpots.filter(
              (item) => hotModel.id !== item.id
            )
            this.$bus.$emit('onRemoveHotpot', hotModel)
          })
        })
        .catch(() => {})
    },
    // 删除热点
    onDelCurrentHotpoint() {
      // eslint-disable-next-line no-unused-vars
      removeHotpot(this.hotModel.id).then((result) => {
        this.hotpots = this.hotpots.filter(
          (item) => this.hotModel.id !== item.id
        )
        this.$bus.$emit('onRemoveHotpot', this.hotModel)
        this.updateHot = false
        this.hotDrawer = true
        this.reset()
      })
    },
    // 根据图标大小类型返回对应的长宽
    getIconSize(type) {
      if (type === 'mini') {
        return {
          width: defaultHotpotConfig.miniSize[0],
          height: defaultHotpotConfig.miniSize[1],
        }
      }

      if (type === 'medium') {
        return {
          width: defaultHotpotConfig.mediumSize[0],
          height: defaultHotpotConfig.mediumSize[1],
        }
      }

      return {
        width: defaultHotpotConfig.bigSize[0],
        height: defaultHotpotConfig.bigSize[1],
      }
    },
    // 触发添加热点表单抽屉关闭
    handleHotFormClose() {
      this.hotDrawer = false
      this.reset()
      this.$bus.$emit('onHotDrawerStatusChange', this.hotDrawer)
    },
    // 重置热点表单
    reset() {
      this.hotModel = Object.assign({}, defaultModel)
      this.hotModel.imgUrls = []
      this.$refs.hotForm.resetFields()
      this.iconTab = 'vr'
      if (this.$refs.iconPicker) {
        this.$refs.iconPicker.currentKey = this.hotModel.icon
      }
    },
    // 打开添加标记热点表单抽屉
    async openHotForm() {
      await this.getProduct()
      console.log('点击添加热点')
      this.updateHot = false
      this.hotDrawer = true
      this.$bus.$emit('onHotDrawerStatusChange', this.hotDrawer)
    },
    // 清空热点
    removeAllHotpots() {
      this.$confirm('确认要清空当前场景下所有热点吗？', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
      })
        .then(() => {
          // eslint-disable-next-line no-unused-vars
          clearHotpots(this.sceneId).then((_result) => {
            this.hotpots = []
            this.$emit('onClearHotPoints')
          })
        })
        .catch(() => {})
    },
    // 触发图标标记
    onIconChange(value) {
      this.$set(this.hotModel, 'icon', value)
    },
    // 图片上传成功
    onUploadSuccess(file) {
      this.hotModel.imgUrls.push(file.url)
    },
    // 图片移除
    onUploadRemove(file) {
      let url = ''
      if (file.response) {
        url = file.response.data.url
      }
      if (file.url) {
        url = file.url
      }
      this.hotModel.imgUrls = this.hotModel.imgUrls.filter(
        (value) => value !== url
      )
    },
    onVideoUploadSuccess(file) {
      let url = ''
      if (file.response) {
        url = file.response.data.url
      }
      if (file.url) {
        url = file.url
      }
      this.hotModel.videoUrl = url
    },
    // 区域绘制开关
    onDrawToolFormSwitch(value) {
      this.$emit(
        'onDrawToolFormSwitch',
        value === 'on',
        this.drawToolForm.rectangle === 'on'
      )
      // if (value === 'on' && this.drawTool) {
      //   this.drawTool.toggleDrawing()
      // }
    },
    // 删除最后一个绘制点
    onDrawToolRemoveLastPoint() {
      this.$emit('onDrawToolRemoveLastPoint')
    },
    // 添加物联网设备
    addIotDevices() {
      this.$emit('onHotDrawerNoOpenDialog', false)
      this.$refs.iotDialog.open(this.iotDevice)
    },
    onSelectedIotDevice(device) {
      this.$emit('onHotDrawerNoOpenDialog', true)
      this.iotDevice = device
      this.hotModel.title = device.name
      switch (device.category) {
        case 2:
          this.hotModel.icon = 'weather'
          break
        case 3:
          this.hotModel.icon = 'soil'
          break
        case 4:
          this.hotModel.icon = 'pest'
          break
        case 5:
          this.hotModel.icon = 'camera2_3d'
          break
        case 6:
          this.hotModel.icon = 'smart'
          break
      }
      if (this.$refs.iconPicker) {
        const icon = this.$refs.iconPicker.changeKey(this.hotModel.icon)
        if (!this.iotDevice.image) {
          this.iotDevice.image = icon.url
        }
      }
    },
    onIotDialogClose() {
      console.log('onIotDialogClose')
      this.$emit('onHotDrawerNoOpenDialog', true)
    }
  },
}
</script>
